mapper.select:
select hliw.*,(select scvb.meaning from sys_code_value_b scvb , sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scb.code in ('HLS.PLEDGE_TYPE','HLS.MORTGAGE_TYPE') and scvb.value = hliw.WARRANT_TYPE ) WARRANT_TYPE_N, (select scvb.meaning from sys_code_value_b scvb , sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scb.code = 'SYS.YES_NO' and scvb.value = hliw.IF_PUT_IN_STORAGE )IF_PUT_IN_STORAGE_N, (select su.description from sys_user su where su.user_id = hliw.WARRANT_MORTGAGOR) WARRANT_MORTGAGOR_N, (select scvb.meaning FROM sys_code_value_b scvb, sys_code_b scb WHERE scvb.CODE_ID = scb.CODE_ID and scb.code = 'WARRANT.FILE_TYPE' and scvb.value = hliw.FILE_TYPE) FILE_TYPE_N from hls_lease_item_warrant hliw
1=1
and hliw.warrant_id = #{warrantId}

select hliw.*,hli.lease_item_code,hli.FULL_NAME,(select meaning from sys_code_value_b_v where code = 'HLS.COLLATERAL_TYPE' and code_value = hli.LEASE_ITEM_TYPE) LEASE_ITEM_TYPE_N, (select su.description from sys_user su where su.user_id = hli.MORTGAGOR) MORTGAGOR_N from hls_lease_item_warrant hliw,hls_lease_item hli
hli.lease_item_id = hliw.lease_item_id
and hli.lease_item_id = #{leaseItemId}

select * from (SELECT pp.project_id, pp.contract_number, pp.contract_name, (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = pp.tenant_id) as bp_name, pp.host_unit_id, (SELECT fou.unit_name FROM fnd_org_unit fou where fou.unit_id = pp.host_unit_id) as unit_name, (SELECT su.description FROM sys_user su where su.user_id = pp.host_project_manager) as host_project_manager, pp.contract_status, hds2.description contract_status_desc FROM prj_project pp LEFT JOIN (select * FROM hls_document_status t1 WHERE t1.document_category = 'CON_CONTRACT') hds2 ON hds2.status_code = nvl(pp.contract_status, 'NEW') where pp.contract_number is not null and pp.data_class = 'VIRTUAL_CON' order by pp.last_update_date desc)v
and v.contract_number like #{contractNumber}
and v.contract_name like #{contractName}
and v.bp_name like #{bpName}
and v.unit_name like #{unitName}
and v.contract_status = #{contractStatus}

select t.business_type as business_type
from hls_business_type t
where t.document_category = #{documentCategory}
and t.description = #{documentCategoryN}

SELECT t.document_type as business_document_type
  FROM hls_document_type t
 where t.document_category = #{documentCategory}
 and t.description =#{businessTypeN}

select t.document_type as business_document_type_n
  from hls_document_type t
 where t.document_category = #{documentCategory}
   and t.business_type = #{businessType}
   and t.document_type = #{businessDocumentType}
